import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"前端架构专题","description":"7 年经验面试必问：\\"你们项目怎么分层？大型项目目录怎么组织？\\"","frontmatter":{},"headers":[],"relativePath":"前端/architecture/index.md","filePath":"前端/architecture/index.md","lastUpdated":1793932732000}'),i={name:"前端/architecture/index.md"};function n(l,t,s,c,d,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="前端架构专题" tabindex="-1">前端架构专题 <a class="header-anchor" href="#前端架构专题" aria-label="Permalink to &quot;前端架构专题&quot;">​</a></h1><blockquote><p>7 年经验面试必问：<strong>&quot;你们项目怎么分层？大型项目目录怎么组织？&quot;</strong></p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-前端分层架构">前端分层架构</a> — UI 层 / 业务层 / 数据层 / 基础设施层</li><li><a href="./2-大型项目目录结构">大型项目目录结构</a> — 按业务/按功能/按 DDD + 真实案例</li><li><a href="./3-设计系统">设计系统 Design System</a> — Design Token / 组件库 / 主题 / Storybook</li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>架构三件套:<strong>分层</strong>(UI / 业务 / 数据 / 基础设施)、<strong>目录</strong>(按业务 vs 按功能 vs DDD)、<strong>设计系统</strong>(Token / 组件库 / 主题)。</li><li>面试标准答法:先讲分层原则(依赖单向、UI 不直接调接口),再讲目录组织(按业务域聚合优于按文件类型),最后讲设计系统(统一视觉与交互)。</li><li>分层的核心价值是<strong>可替换</strong>:换 UI 框架、换数据源,影响范围被限制在对应层。</li><li>大型项目目录要给出<strong>真实取舍</strong>:模块数量、跨模块引用规则、公共代码放哪、什么时候允许互相 import。</li><li>面试加分:能说清「什么不进公共层」——业务耦合的代码不要为了复用硬抽公共,那是灾难的起点。</li></ul>',6)])])}const g=e(i,[["render",n]]);export{u as __pageData,g as default};
